(function(){'use strict';
const P=window.SMRFProject,W=window.SMRFWorkspace,$=id=>document.getElementById(id),escape=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(v,d=2)=>Number(v).toFixed(d),sign=v=>(v>0?'+':'')+fmt(v,1);
let project=null,surfaces={},settings=P.defaults(),selected=null,baselineHash='',lastRequest=null,returned=null,filesRead=[];
async function hash(text){const bytes=new TextEncoder().encode(text);return Array.from(new Uint8Array(await window.crypto.subtle.digest('SHA-256',bytes)),x=>x.toString(16).padStart(2,'0')).join('');}
function message(text,error=false){$('cp-load-status').textContent=text;$('cp-load-status').classList.toggle('error',error);}
function download(value,name,type='application/json'){const text=typeof value==='string'?value:JSON.stringify(value,null,2),blob=new Blob([text],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function preview(){try{return {data:P.preview(project,settings,surfaces),error:null};}catch(error){return {data:null,error:error.message};}}
function changed(){lastRequest=null;returned=null;render();}
function ready(){const loaded=!!project;for(const id of ['cp-summary','cp-custom-map','cp-custom-inspector','cp-comparison-panel','cp-diagnostics-panel'])$(id).hidden=!loaded;for(const id of ['cp-empty-workspace','cp-unlock-note'])$(id).hidden=loaded;$('cp-controls').disabled=!loaded;for(const id of ['cp-source','cp-parking','cp-green','cp-streets','cp-width','cp-verified','cp-terrain','cp-alignment','cp-export','cp-reset','cp-template','cp-clear','cp-import-result'])$(id).disabled=!loaded;}
async function readFiles(fileList){
 try{const files=Array.from(fileList);if(!files.length)return;if(files.length>8||files.reduce((a,f)=>a+f.size,0)>50*1024*1024||files.some(f=>f.size>20*1024*1024))throw Error('Use at most 8 files, 20 MB each and 50 MB total.');
 const inputs=files.filter(f=>/\.inp$/i.test(f.name)),csv=files.filter(f=>/\.csv$/i.test(f.name)),geo=files.filter(f=>/\.(geojson|json)$/i.test(f.name));if(inputs.length>1||csv.length>1||inputs.length+csv.length+geo.length!==files.length)throw Error('Choose one INP, at most one CSV, and optional GeoJSON files.');if(!inputs.length&&!project)throw Error('Load a baseline INP first.');
 message('Reading and validating files locally…');const source=inputs.length?await inputs[0].text():project.source_text;const next=P.parseINP(source,inputs[0]?.name||project.name),nextSurfaces=csv.length?P.parseSurfaces(await csv[0].text(),next):inputs.length?{}:surfaces;
 if(geo.length)P.addGeometry(next,await Promise.all(geo.map(async f=>JSON.parse(await f.text()))));else if(!inputs.length){next.geo=project.geo;next.coordinate_source=project.coordinate_source;}
 const nextHash=await hash(source);project=next;surfaces=nextSurfaces;baselineHash=nextHash;settings=P.defaults();selected={type:'c',id:next.catchments[0].id};lastRequest=null;returned=null;filesRead=files.map(f=>f.name);$('cp-search').value='';ready();render();message(`${project.name}: ${project.catchments.length} subcatchments, ${project.nodes.length} nodes and ${project.links.length} links. ${Object.keys(surfaces).length} surface rows loaded. Customization options are enabled. Data remain in this browser session.`);
 }catch(error){message('Files not loaded: '+error.message,true);}
}
function readControls(){if(!project)return;settings.source=$('cp-source').value;for(const k of ['parking','green','streets','verified','terrain','alignment'])settings[k]=$('cp-'+k).checked;settings.width_m=Number($('cp-width').value);if(settings.source==='inventory')settings.green=false;changed();}
function controls(){for(const k of ['parking','green','streets','verified','terrain','alignment'])$('cp-'+k).checked=settings[k];$('cp-source').value=settings.source;$('cp-width').value=settings.width_m;$('cp-parking').disabled=!project||settings.source==='manual';$('cp-green').disabled=!project||settings.source!=='baseline';$('cp-streets').disabled=!project||settings.source==='manual';$('cp-width').disabled=!project||!settings.streets||settings.source==='manual';$('cp-verified').disabled=!project||settings.source==='manual';}
function options(){const query=$('cp-search').value.trim().toLowerCase(),groups=[['c','Subcatchments',project.catchments],['l','Links',project.links],['n','Nodes',project.nodes]];let html='';for(const [type,title,rows]of groups){const found=rows.filter(x=>x.id.toLowerCase().includes(query)).slice(0,500);if(selected?.type===type&&!found.some(x=>x.id===selected.id)){const item=rows.find(x=>x.id===selected.id);if(item)found.unshift(item);}html+=`<optgroup label="${title}">${found.map(x=>`<option value="${type}:${escape(x.id)}">${escape(x.id)}</option>`).join('')}</optgroup>`;}$('cp-object').innerHTML=html;$('cp-object').value=selected.type+':'+selected.id;}
function select(value){const type=value.slice(0,1),id=value.slice(2),rows=type==='c'?project.catchments:type==='l'?project.links:project.nodes;if(!rows.some(x=>x.id===id))return;selected={type,id};const v=preview();options();inspector(v.data);map(v.data);}
function kv(k,v){return `<div class="kv"><span>${k}</span><strong>${escape(v)}</strong></div>`;}
function inspector(data){let html='';if(selected.type==='c'){const c=project.catchments.find(x=>x.id===selected.id),r=data?.rows.find(x=>x.id===c.id);html=`<div class="object-heading"><span class="object-tag">IMPORTED SUBCATCHMENT</span><h3>${escape(c.id)}</h3><p>Baseline attributes from your INP</p></div>${kv('Gross area',fmt(c.area_ha)+' ha')}${kv('Runoff outlet',c.outlet)}${kv('Surface slope',fmt(c.slope_pct)+'%')}${kv('Baseline %Imperv',fmt(c.impervious_pct,1)+'%')}<div class="inspector-stat"><span class="field-label">PROPOSED %IMPERV</span><div class="stat-value">${r?fmt(r.proposed_pct,1):'—'}<small>${r?'%':''}</small></div><span class="small">${r?sign(r.delta_pp)+' pp from baseline':'Resolve missing or invalid surface values.'}</span></div>`;
 if(settings.source==='manual')html+=`<div class="manual-field"><label class="field-label" for="cp-manual">Set fraction (%)</label><input id="cp-manual" type="number" min="0" max="100" step="0.1" value="${fmt(settings.manual[c.id]??c.impervious_pct,1)}"><p id="cp-manual-error" class="error" hidden></p></div>`;
 const s=surfaces[c.id];html+=`<div class="inspector-notice">${s?Object.entries(s).filter(([,v])=>v!==null).map(([k,v])=>escape(k)+': '+fmt(v)).join('<br>'):'No surface CSV row supplied for this catchment.'}</div>`;
 }else if(selected.type==='l'){const l=project.links.find(x=>x.id===selected.id);html=`<div class="object-heading"><span class="object-tag">IMPORTED ${escape(l.kind.toUpperCase())}</span><h3>${escape(l.id)}</h3><p>${escape(l.from)} → ${escape(l.to)}</p></div>${kv('Length',l.length_m===null?'Not applicable':fmt(l.length_m)+' m')}${kv('Cross-section',l.shape||'Not provided')}${l.geometry_reference?kv('Geometry reference',l.geometry_reference):''}${kv(l.shape==='CIRCULAR'?'Diameter':'Geometry 1',l.geometry1_m===null?'Not provided':fmt(l.geometry1_m,3)+' m')}<p class="inspector-notice">Input dimensions only. Flow, capacity, surcharge and hydraulic accuracy have not been calculated by the site.</p>`;
 }else{const n=project.nodes.find(x=>x.id===selected.id);html=`<div class="object-heading"><span class="object-tag">IMPORTED ${escape(n.kind.toUpperCase())}</span><h3>${escape(n.id)}</h3><p>Input levels in the model’s own vertical datum</p></div>${kv('Invert level',fmt(n.invert_m)+' m')}${kv('Maximum depth',n.max_depth_m===null?'Not read for this node type':fmt(n.max_depth_m)+' m')}${kv('Incoming links',project.links.filter(l=>l.to===n.id).length)}${kv('Outgoing links',project.links.filter(l=>l.from===n.id).length)}<p class="inspector-notice">Structural connectivity checks do not establish drainage performance or account for dynamic reverse flow.</p>`;}$('cp-inspector').innerHTML=html;}
function map(data){const geo=project.geo,allPoints=[...Object.values(geo.nodes),...Object.values(geo.links).flat(),...Object.values(geo.catchments).flat(2)];$('cp-map-source').textContent=project.coordinate_source;$('cp-no-map').hidden=allPoints.length>0;if(!allPoints.length){$('cp-map-objects').innerHTML='';$('cp-map-count').textContent='No usable coordinates';return;}
 let xmin=Infinity,xmax=-Infinity,ymin=Infinity,ymax=-Infinity;for(const [x,y]of allPoints){xmin=Math.min(xmin,x);xmax=Math.max(xmax,x);ymin=Math.min(ymin,y);ymax=Math.max(ymax,y);}const scale=Math.min(730/Math.max(xmax-xmin,1e-9),410/Math.max(ymax-ymin,1e-9)),ox=400-(xmax+xmin)/2*scale,oy=240+(ymax+ymin)/2*scale,pt=([x,y])=>[ox+x*scale,oy-y*scale],pointString=a=>a.map(x=>pt(x).map(v=>v.toFixed(2)).join(',')).join(' '),sel=(type,id)=>selected.type===type&&selected.id===id?' selected':'';
 const pct=new Map((data?.rows||[]).map(x=>[x.id,x.proposed_pct]));let html='',count=0;
 for(const c of project.catchments.slice(0,3000)){const rings=geo.catchments[c.id];if(!rings?.length)continue;const value=pct.get(c.id)??c.impervious_pct,fill=value<35?'#e5edd8':value<55?'#c8dba7':'#a6c386';html+=`<path d="${rings.filter(r=>r.length>=3).map(r=>'M'+pointString(r)+'Z').join(' ')}" fill="${fill}" fill-rule="evenodd" stroke="#9aaf87" stroke-width="1" class="custom-object${sel('c',c.id)}" tabindex="0" role="button" data-real-object="c:${escape(c.id)}" aria-label="Subcatchment ${escape(c.id)}"><title>${escape(c.id)} · ${fmt(value,1)}% impervious</title></path>`;count++;}
 for(const l of project.links.slice(0,3000)){const pts=geo.links[l.id];if(!pts||pts.length<2)continue;html+=`<polyline points="${pointString(pts)}" fill="none" stroke="#2d7958" stroke-width="2.5" class="custom-object${sel('l',l.id)}" data-real-object="l:${escape(l.id)}" tabindex="0" role="button" aria-label="Link ${escape(l.id)}"><title>${escape(l.id)}</title></polyline>`;count++;}
 for(const node of project.nodes.slice(0,3000)){const xy=geo.nodes[node.id];if(!xy)continue;const [x,y]=pt(xy);html+=`<circle cx="${x.toFixed(2)}" cy="${y.toFixed(2)}" r="4" fill="#fff" stroke="#2b7659" stroke-width="1.5" class="custom-object${sel('n',node.id)}" data-real-object="n:${escape(node.id)}" tabindex="0" role="button" aria-label="Node ${escape(node.id)}"><title>${escape(node.id)}</title></circle>`;if(project.nodes.length<120)html+=`<text x="${(x+7).toFixed(2)}" y="${(y-6).toFixed(2)}" class="custom-map-label">${escape(node.id)}</text>`;count++;}$('cp-map-objects').innerHTML=html;$('cp-map-count').textContent=count+' mapped objects · up to 3,000 per type';}
function render(){if(!project)return;controls();const v=preview(),t=v.data,d=P.diagnostics(project);$('cp-refinement-error').hidden=!v.error;$('cp-refinement-error').textContent=v.error||'';$('cp-export').disabled=!!v.error||d.some(x=>x.status==='error');
 const card=(label,value,unit,note)=>`<div class="metric"><div class="metric-label">${label}</div><div class="metric-value">${value}<small>${unit}</small></div><div class="metric-foot">${note}</div></div>`;
 const area=project.catchments.reduce((a,c)=>a+c.area_ha,0),base=project.catchments.reduce((a,c)=>a+c.area_ha*c.impervious_pct/100,0)/area*100;
 $('cp-summary').innerHTML=card('Imported study area',fmt(area),'ha',escape(project.name))+card('Baseline imperviousness',fmt(base,1),'%',project.flow_units+' input · '+project.unit_system+' units normalized')+card('Proposed imperviousness',t?fmt(t.proposed_pct,1):'—',t?'%':'',t?sign(t.delta_pp)+' percentage points':'Preview needs valid surface inputs')+card('Model objects',project.nodes.length+project.links.length,'',project.catchments.length+' catchments · '+project.nodes.length+' nodes · '+project.links.length+' links');
 const byId=new Map((t?.rows||[]).map(x=>[x.id,x]));$('cp-comparison').innerHTML=project.catchments.slice(0,500).map(c=>{const r=byId.get(c.id);return `<tr><td><strong>${escape(c.id)}</strong></td><td>${fmt(c.area_ha)}</td><td>${fmt(c.impervious_pct,1)}</td><td>${r?fmt(r.proposed_pct,1):'—'}</td><td>${r?sign(r.delta_pp):'—'}</td></tr>`;}).join('');$('cp-total').innerHTML=`<tr><td>Area-weighted total</td><td>${fmt(area)}</td><td>${fmt(base,1)}</td><td>${t?fmt(t.proposed_pct,1):'—'}</td><td>${t?sign(t.delta_pp):'—'}</td></tr>`;
 $('cp-checks').innerHTML=d.map(x=>`<div class="check-row"><span class="check-symbol ${x.status}">${x.status==='pass'?'✓':'!'}</span><div><strong>${x.name}</strong><p>${escape(x.detail)}</p></div></div>`).join('')+project.warnings.map(x=>`<div class="model-warning">${escape(x)}</div>`).join('');options();inspector(t);map(t);renderResult();}
function renderResult(){if(!returned){$('cp-result').textContent='No matching runner result imported. Hydraulic simulation has not been executed by this site.';$('cp-comparison-status').textContent='BROWSER PREVIEW';return;}const pending=returned.pending_operations||[];$('cp-result').innerHTML=`<strong>Matching Python result imported.</strong> ${returned.catchments.length} surface fractions were checked against the current preview. A separate refined INP was returned.<br>${pending.length?'Pending: '+escape(pending.join(', '))+'.<br>':''}SWMM execution: ${escape(returned.engine?.status||'not_requested')} (reported by the local runner; no hydraulic comparison is inferred here).<br><button class="button primary" id="cp-download-refined">Download returned refined.inp</button>`;$('cp-comparison-status').textContent='PYTHON RESULT CHECKED';}
async function acceptResult(r){if(!project)throw Error('Load the matching baseline INP first.');if(r.schema!=='smrf-processing-result/v1'||r.baseline_sha256!==baselineHash)throw Error('This result does not match the loaded baseline fingerprint.');if(lastRequest&&r.request_id!==lastRequest.request_id)throw Error('This result belongs to a different processing request.');if(JSON.stringify(P.settings(r.request_settings,project))!==JSON.stringify(P.settings(settings,project)))throw Error('Result settings differ from the current choices. Restore the exported refinement choices first.');const expected=P.preview(project,settings,surfaces),expectedById=new Map(expected.rows.map(x=>[x.id,x]));if(!Array.isArray(r.catchments)||r.catchments.length!==expected.rows.length)throw Error('Result catchment count does not match the model.');const seen=new Set();for(const row of r.catchments){const e=expectedById.get(row.id);if(!e||seen.has(row.id)||!Number.isFinite(row.proposed_pct)||Math.abs(row.proposed_pct-e.proposed_pct)>1e-6)throw Error('Result surface fractions differ from the checked preview.');seen.add(row.id);}if(typeof r.refined_inp!=='string'||await hash(r.refined_inp)!==r.refined_inp_sha256)throw Error('The refined INP fingerprint is invalid.');if(P.structure(r.refined_inp)!==P.structure(project.source_text))throw Error('The returned INP changed fields beyond %Imperv.');const refined=P.parseINP(r.refined_inp,'Returned refined model');if(refined.catchments.length!==project.catchments.length||refined.nodes.length!==project.nodes.length||refined.links.length!==project.links.length)throw Error('The returned model changed unsupported geometry or object counts.');for(const c of refined.catchments){const e=expectedById.get(c.id);if(!e||Math.abs(c.area_ha-e.area_ha)>1e-6||Math.abs(c.impervious_pct-e.proposed_pct)>1e-5)throw Error('Returned INP fractions or areas do not match.');}returned=r;renderResult();W.notify('Baseline, choices and returned surface fractions match.');}
$('cp-upload').addEventListener('click',()=>$('cp-files').click());$('cp-files').addEventListener('change',async e=>{await readFiles(e.target.files);e.target.value='';});$('cp-dropzone').addEventListener('dragover',e=>{e.preventDefault();$('cp-dropzone').classList.toggle('dragging',true);});$('cp-dropzone').addEventListener('dragleave',()=>$('cp-dropzone').classList.toggle('dragging',false));$('cp-dropzone').addEventListener('drop',async e=>{e.preventDefault();$('cp-dropzone').classList.toggle('dragging',false);await readFiles(e.dataTransfer.files);});
$('cp-start-upload').addEventListener('click',()=>$('cp-files').click());
$('cp-clear').addEventListener('click',()=>{project=null;surfaces={};settings=P.defaults();selected=null;returned=null;lastRequest=null;baselineHash='';filesRead=[];ready();controls();for(const id of ['cp-summary','cp-map-objects','cp-inspector','cp-comparison','cp-total','cp-checks'])$(id).innerHTML='';$('cp-refinement-error').hidden=true;message('Custom data cleared. Choose your .inp to enable customization again.');$('cp-result').textContent='No runner result imported.';});$('cp-reset').addEventListener('click',()=>{if(!project)return;settings=P.defaults();changed();});
for(const k of ['source','parking','green','streets','width','verified','terrain','alignment'])$('cp-'+k).addEventListener('change',readControls);$('cp-object').addEventListener('change',e=>select(e.target.value));$('cp-search').addEventListener('input',()=>{if(project)options();});
$('cp-inspector').addEventListener('change',e=>{if(e.target.id!=='cp-manual')return;const x=Number(e.target.value);if(!e.target.value.trim()||!Number.isFinite(x)||x<0||x>100){$('cp-manual-error').textContent='Enter 0–100%.';$('cp-manual-error').hidden=false;return;}settings.manual[selected.id]=x;changed();});
$('cp-map').addEventListener('click',e=>{const obj=e.target.closest('[data-real-object]');if(obj&&project)select(obj.dataset.realObject);});$('cp-map').addEventListener('keydown',e=>{if(e.key!=='Enter'&&e.key!==' ')return;const obj=e.target.closest('[data-real-object]');if(obj&&project){e.preventDefault();select(obj.dataset.realObject);const next=Array.from(document.querySelectorAll('[data-real-object]')).find(x=>x.dataset.realObject===obj.dataset.realObject);if(next)next.focus();}});$('cp-fit').addEventListener('click',()=>{if(project)map(preview().data);});
$('cp-template').addEventListener('click',()=>{if(!project)return;const quote=x=>'"'+String(x).replace(/"/g,'""')+'"';download('catchment_id,roof_ha,road_ha,parking_ha,green_correction_ha,baseline_road_width_m\r\n'+project.catchments.map(c=>quote(c.id)+',,,,,').join('\r\n')+'\r\n','smrf-surface-template.csv','text/csv');});
$('cp-export').addEventListener('click',()=>{try{const id='request_'+window.crypto.randomUUID(),request=P.request(project,settings,surfaces,baselineHash,id);lastRequest=request;download(request,'smrf-processing-request.json');W.notify('Request exported. It contains your model; run it locally with the Python runner.');}catch(e){message(e.message,true);}});
$('cp-import-result').addEventListener('click',()=>$('cp-result-file').click());$('cp-result-file').addEventListener('change',async e=>{const f=e.target.files?.[0];if(!f)return;try{if(f.size>30*1024*1024)throw Error('Use a result pack smaller than 30 MB.');await acceptResult(JSON.parse(await f.text()));}catch(error){W.notify('Result not imported: '+error.message);}finally{e.target.value='';}});$('cp-result').addEventListener('click',e=>{if(e.target.id==='cp-download-refined'&&returned)download(returned.refined_inp,'refined.inp','text/plain');});
ready();controls();
})();
